#!/usr/bin/env python3
"""scripts/ci/generated_files_guard.py: a pull request never adds a committed generated file.

Each test builds a scratch git repository with a base commit and a head commit and runs the
guard's check on them. No network.
"""
from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts" / "ci"))

import generated_files_guard as guard  # noqa: E402

MANIFEST = {
    "conventions": ["**/*.generated.*", "**/generated/**"],
    "committed": [{"paths": ["**/Cargo.lock"], "why": "a lockfile is an input"}],
    "generators": [
        {"id": "schema", "generator": "tools/gen-schema.py", "outputs": ["app/Schema+*.generated.swift"],
         "inputs": ["schemas/**"], "status": "committed"},
        {"id": "strings", "generator": "tools/gen-strings.mjs", "outputs": ["web/**/generated/strings.json"],
         "status": "build"},
    ],
}
SCHEMA_OUT = "app/Schema+Chats.generated.swift"
# A generator for the scratch repositories: SCHEMA_OUT from schemas/chats.json, and --check exits 1 when
# SCHEMA_OUT differs from what it would write.
SCHEMA_GENERATOR = """import json, sys
from pathlib import Path
out = Path("app/Schema+Chats.generated.swift")
text = ("// GENERATED by tools/gen-schema.py. Do not edit.\\n"
        + "let schema = " + json.dumps(json.loads(Path("schemas/chats.json").read_text()), sort_keys=True) + "\\n")
if "--check" in sys.argv[1:]:
    sys.exit(0 if out.is_file() and out.read_text() == text else 1)
out.write_text(text)
"""


def rendered(schema: dict) -> str:
    """What SCHEMA_GENERATOR writes for a schemas/chats.json holding `schema`."""
    return ("// GENERATED by tools/gen-schema.py. Do not edit.\n"
            f"let schema = {json.dumps(schema, sort_keys=True)}\n")


def with_check(check=("--check",), generator="tools/gen-schema.py") -> str:
    data = json.loads(manifest())
    data["generators"][0].update(check=check if isinstance(check, str) else list(check), generator=generator)
    return json.dumps(data)


class Repo:
    def __init__(self, root: Path):
        self.root = root
        root.mkdir(parents=True)
        self.git("init", "-q", "-b", "main")

    def git(self, *args: str) -> str:
        return subprocess.run(
            ["git", "-c", "user.name=t", "-c", "user.email=t@example.com", "-c", "core.hooksPath=/dev/null",
             "-c", "commit.gpgsign=false", *args],
            cwd=self.root, check=True, capture_output=True, text=True).stdout.strip()

    def write(self, files: dict[str, str | None]) -> None:
        for path, text in files.items():
            full = self.root / path
            if text is None:
                full.unlink()
                continue
            full.parent.mkdir(parents=True, exist_ok=True)
            full.write_text(text, encoding="utf-8")

    def commit(self, files: dict[str, str | None]) -> str:
        self.write(files)
        self.git("add", "-A")
        self.git("commit", "-q", "--allow-empty", "-m", "change")
        return self.git("rev-parse", "HEAD")


def manifest(**changes) -> str:
    data = json.loads(json.dumps(MANIFEST))
    data.update(changes)
    return json.dumps(data)


class GuardTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.repo = Repo(Path(self.tmp.name) / "repo")
        self.base = self.repo.commit({
            guard.MANIFEST: manifest(),
            guard.BASELINE: "# baseline\nlegacy/old.generated.ts\n",
            "legacy/old.generated.ts": "x\n",
            "schemas/chats.json": "{}\n",
            SCHEMA_OUT: "// GENERATED by tools/gen-schema.py. Do not edit.\n",
            "README.md": "hello\n",
        })

    def tearDown(self):
        self.tmp.cleanup()

    def check(self, files: dict[str, str | None]) -> tuple[list[str], list[str]]:
        self.repo.git("reset", "-q", "--hard", self.base)
        head = self.repo.commit(files)
        return guard.check(self.repo.root, self.base, head, [])

    def assertFails(self, files, needle):
        errors, _ = self.check(files)
        self.assertTrue(any(needle in e for e in errors), f"expected an error naming {needle!r}, got {errors}")

    def assertPasses(self, files):
        errors, _ = self.check(files)
        self.assertEqual(errors, [])

    def test_a_base_without_the_manifest_checks_nothing(self):
        repo = Repo(Path(self.tmp.name) / "fresh")
        base = repo.commit({"README.md": "x\n"})
        head = repo.commit({"a/b.generated.ts": "x\n", guard.MANIFEST: manifest()})
        errors, notes = guard.check(repo.root, base, head, [])
        self.assertEqual(errors, [])
        self.assertTrue(any("nothing to check" in n for n in notes))

    def test_an_ordinary_file_passes(self):
        self.assertPasses({"src/main.py": "print('hi')\n", "README.md": "hello again\n"})

    def test_a_conventionally_named_new_file_fails(self):
        self.assertFails({"web/src/thing.generated.ts": "export {}\n"}, "web/src/thing.generated.ts")
        self.assertFails({"web/src/generated/protocol.ts": "export {}\n"}, "its name marks it generated")

    def test_a_generated_header_fails_and_prose_does_not(self):
        self.assertFails({"src/table.rs": "// Generated by tools/x.py. Do not edit.\n"}, "header says it is generated")
        self.assertFails({"src/b.ts": "// @generated by codegen\n"}, "src/b.ts")
        self.assertPasses({"docs/notes.md": "The schema file is generated by tools/gen-schema.py.\n"})

    def test_string_literals_and_prose_are_not_headers(self):
        self.assertPasses({"tools/gen.py": 'HEADER = "// GENERATED by tools/gen.py. Do not edit."\n'})
        self.assertPasses({"docs/codegen.md": "Mark outputs with an @generated comment.\n"})
        self.assertFails({"src/c.json": '{"_comment": "GENERATED by tools/x.py"}\n'}, "src/c.json")

    def test_an_output_of_a_generator_the_change_declares_fails(self):
        gens = json.loads(manifest())["generators"]
        gens.append({"id": "table", "generator": "t.py", "outputs": ["src/table.ts"], "status": "build"})
        self.assertFails({guard.MANIFEST: manifest(generators=gens), "src/table.ts": "export {}\n"},
                         "src/table.ts: a new committed generated file")

    def test_exports_come_from_each_revision(self):
        exports = "OUTPUTS = ((('out/a.json',), r'^in/', 'a'),)\n"
        repo = Repo(Path(self.tmp.name) / "exports")
        base = repo.commit({guard.MANIFEST: manifest(), guard.OUTPUTS: exports})
        head = repo.commit({"out/a.json": "{}\n", "in/a.txt": "x\n"})
        self.assertEqual(guard.check(repo.root, base, head)[0], [])
        wider = exports.replace("),)", "), (('out/b.json',), r'^in/', 'b'))")
        head = repo.commit({guard.OUTPUTS: wider, "out/b.json": "{}\n"})
        errors, _ = guard.check(repo.root, head + "~1", head)
        self.assertTrue(any("out/b.json is a new committed export" in e for e in errors), errors)

    def test_a_new_output_of_a_committed_generator_passes(self):
        self.assertPasses({"app/Schema+Feed.generated.swift": "// GENERATED by tools/gen-schema.py\n",
                           "schemas/feed.json": "{}\n"})

    def test_an_output_of_a_build_generator_fails(self):
        self.assertFails({"web/pages/generated/strings.json": "{}\n"}, "status build")

    def test_a_lockfile_is_committed_by_design(self):
        self.assertPasses({"crates/Cargo.lock": "# @generated by Cargo\n"})

    def test_the_rules_come_from_the_base(self):
        loosened = manifest(conventions=[])
        self.assertFails({guard.MANIFEST: loosened, "web/x.generated.ts": "x\n"}, "web/x.generated.ts")

    def test_a_new_or_widened_committed_generator_fails(self):
        gens = json.loads(manifest())["generators"]
        added = gens + [{"id": "new", "generator": "t.py", "outputs": ["n/*.ts"], "status": "committed"}]
        self.assertFails({guard.MANIFEST: manifest(generators=added)}, "new is \"committed\"")
        back = [dict(g, status="committed") if g["id"] == "strings" else g for g in gens]
        self.assertFails({guard.MANIFEST: manifest(generators=back)}, "as 'build'")
        wider = [dict(g, outputs=g["outputs"] + ["more/*"]) if g["id"] == "schema" else g for g in gens]
        self.assertFails({guard.MANIFEST: manifest(generators=wider)}, "widens its committed outputs")

    def test_moving_a_generator_to_build_time_passes(self):
        gens = [dict(g, status="build") if g["id"] == "schema" else g for g in json.loads(manifest())["generators"]]
        self.assertPasses({guard.MANIFEST: manifest(generators=gens), SCHEMA_OUT: None})

    def test_a_new_by_design_exception_needs_a_ruling_link(self):
        bare = MANIFEST["committed"] + [{"paths": ["**/*.pb"]}]
        self.assertFails({guard.MANIFEST: manifest(committed=bare)}, "has no \"ruling\" link")
        ruled = MANIFEST["committed"] + [{"paths": ["**/*.pb"], "ruling": "https://github.com/o/r/issues/1"}]
        self.assertPasses({guard.MANIFEST: manifest(committed=ruled)})

    def test_the_baseline_only_shrinks(self):
        self.assertFails({guard.BASELINE: "legacy/old.generated.ts\nnew/x.generated.ts\n",
                          "new/x.generated.ts": "x\n"}, "new to the baseline")
        self.assertPasses({guard.BASELINE: "", "legacy/old.generated.ts": None})

    def test_dropping_a_baseline_line_while_the_file_stays_fails(self):
        self.assertFails({guard.BASELINE: ""}, "legacy/old.generated.ts: tracked and generated")

    def test_a_hand_edit_of_an_output_fails_and_a_regeneration_passes(self):
        edited = "// GENERATED by tools/gen-schema.py. Do not edit.\nlet x = 1\n"
        self.assertFails({SCHEMA_OUT: edited}, "changes none of its inputs")
        self.assertPasses({SCHEMA_OUT: edited + "let y = 2\n", "schemas/chats.json": "{\"a\": 1}\n"})

    def stale_base(self, manifest_text: str) -> tuple[Repo, str]:
        """A base whose input changed without a regeneration: schemas/chats.json says {"a": 1}, the
        output still shows {} (what 698b3ef64cf left in DaemonLanePolicy+Fields.generated.swift)."""
        repo = Repo(Path(self.tmp.name) / "stale")
        repo.commit({guard.MANIFEST: manifest_text, guard.BASELINE: "", "tools/gen-schema.py": SCHEMA_GENERATOR,
                     "schemas/chats.json": "{}\n", SCHEMA_OUT: rendered({})})
        base = repo.commit({"schemas/chats.json": "{\"a\": 1}\n"})
        return repo, base

    def head_of(self, repo: Repo, base: str, files: dict[str, str | None]) -> list[str]:
        repo.git("reset", "-q", "--hard", base)
        head = repo.commit(files)
        errors, _ = guard.check(repo.root, base, head, [])
        return errors

    def test_a_regeneration_from_the_bases_inputs_passes_when_the_generator_has_a_check(self):
        repo, base = self.stale_base(with_check())
        self.assertEqual(self.head_of(repo, base, {SCHEMA_OUT: rendered({"a": 1})}), [])

    def test_a_hand_edit_still_fails_when_the_generator_has_a_check(self):
        repo, base = self.stale_base(with_check())
        errors = self.head_of(repo, base, {SCHEMA_OUT: rendered({"a": 1}) + "let y = 2\n"})
        self.assertTrue(any(SCHEMA_OUT in e and "not a regeneration" in e and "exits 1" in e for e in errors),
                        errors)
        # The stale output edited by hand is no regeneration either.
        errors = self.head_of(repo, base, {SCHEMA_OUT: rendered({}) + "let y = 2\n"})
        self.assertTrue(any(SCHEMA_OUT in e and "changes none of its inputs" in e for e in errors), errors)

    def test_a_regeneration_fails_without_a_check(self):
        repo, base = self.stale_base(manifest())
        errors = self.head_of(repo, base, {SCHEMA_OUT: rendered({"a": 1})})
        self.assertTrue(any(SCHEMA_OUT in e and "no \"check\"" in e for e in errors), errors)

    def test_the_check_comes_from_the_base(self):
        """A pull request that adds the check cannot use it for its own regeneration."""
        repo, base = self.stale_base(manifest())
        errors = self.head_of(repo, base, {guard.MANIFEST: with_check(), SCHEMA_OUT: rendered({"a": 1})})
        self.assertTrue(any(SCHEMA_OUT in e and "changes none of its inputs" in e for e in errors), errors)

    def test_a_check_that_cannot_run_counts_as_failed(self):
        repo, base = self.stale_base(with_check(generator="tools/gone.py"))
        errors = self.head_of(repo, base, {SCHEMA_OUT: rendered({"a": 1})})
        self.assertTrue(any(SCHEMA_OUT in e and "tools/gone.py is missing" in e for e in errors), errors)

    def test_a_check_must_be_arguments_to_a_python_generator(self):
        with self.assertRaisesRegex(ValueError, "list of arguments"):
            guard.parse_rules(with_check(check="--check"), "", [])
        with self.assertRaisesRegex(ValueError, "must be a .py script"):
            guard.parse_rules(with_check(generator="tools/gen-schema.mjs"), "", [])

    def test_an_uncovered_file_the_base_already_has_is_a_note_not_a_red(self):
        stray = Repo(Path(self.tmp.name) / "stray")
        base = stray.commit({guard.MANIFEST: manifest(), guard.BASELINE: "", "old/x.generated.ts": "x\n"})
        head = stray.commit({"README.md": "unrelated\n"})
        errors, notes = guard.check(stray.root, base, head, [])
        self.assertEqual(errors, [])
        self.assertTrue(any("old/x.generated.ts" in n and "base" in n for n in notes), notes)
        head = stray.commit({"old/x.generated.ts": "y\n"})
        errors, _ = guard.check(stray.root, head + "~1", head, [])
        self.assertTrue(any("old/x.generated.ts" in e for e in errors), errors)

    def test_deleting_the_manifest_fails(self):
        self.assertFails({guard.MANIFEST: None}, "is deleted")

    def test_the_repository_manifest_parses(self):
        rules = guard.parse_rules((ROOT / guard.MANIFEST).read_text(encoding="utf-8"),
                                  (ROOT / guard.BASELINE).read_text(encoding="utf-8"), [])
        self.assertTrue(rules.generators)
        for generator in rules.generators:
            if generator.check:
                self.assertTrue((ROOT / generator.generator).is_file(), generator.generator)

    def test_the_repository_outputs_module_loads_detached(self):
        """load_exports runs generated_outputs.py from a temporary directory, not the checkout, so
        everything it reads beside itself must be written there too. It reads
        scripts/cmux-next/settings-exports.txt, the one list of the settings exports, and without
        that file the import raised FileNotFoundError and the whole check died (review of #23915)."""
        exports = guard.load_exports(
            (ROOT / guard.OUTPUTS).read_text(encoding="utf-8"),
            (ROOT / guard.SETTINGS_EXPORTS).read_text(encoding="utf-8"))
        self.assertTrue(exports)
        patterns = {pattern for pats, _ in exports for pattern in pats}
        self.assertIn("schemas/settings/settings-schema.json", patterns)

    def test_exports_at_a_revision_carry_that_revisions_list(self):
        """rules_at reads both files at the same revision, so a revision that adds an export to the
        list has it in the rules there and not at the one before."""
        outputs = ("from pathlib import Path\n"
                   "_listed = [l.split('#', 1)[0].strip() for l in "
                   "(Path(__file__).resolve().parent / 'settings-exports.txt').read_text().splitlines()]\n"
                   "OUTPUTS = ((tuple(p for p in _listed if p), r'^in/', 'settings'),)\n")
        repo = Repo(Path(self.tmp.name) / "revision-list")
        repo.commit({guard.MANIFEST: manifest(), guard.OUTPUTS: outputs,
                     guard.SETTINGS_EXPORTS: "out/a.json\n"})
        head = repo.commit({guard.SETTINGS_EXPORTS: "out/a.json\nout/b.json\n", "out/b.json": "{}\n"})
        self.assertEqual({p for pats, _ in guard.rules_at(repo.root, head).exports for p in pats},
                         {"out/a.json", "out/b.json"})
        self.assertEqual({p for pats, _ in guard.rules_at(repo.root, head + "~1").exports for p in pats},
                         {"out/a.json"})


if __name__ == "__main__":
    unittest.main()
